import { jsPDF } from 'jspdf';
var font =
  '';
var callAddFont = function() {
  this.addFileToVFS('Proxima-Nova-Bold-It-bolditalic.ttf', font);
  this.addFont(
    'Proxima-Nova-Bold-It-bolditalic.ttf',
    'ProximaNova-Regular',
    'bolditalic'
  );
};
jsPDF.API.events.push(['addFonts', callAddFont]);
